#!/usr/bin/env node
import { basename } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseArgs } from './lib/pyargparse.mjs';
import { Struct, Int8ul, bytesFromInts } from './lib/pystruct.mjs';

const prog = process.argv[1] ? basename(process.argv[1]) : 'test4.mjs';

function main() {
  const args = parseArgs(process.argv.slice(2), prog);
  const struct = new Struct([
    ['field1', Int8ul],
    ['field2', Int8ul],
  ]);
  let data;
  try {
    data = bytesFromInts([args.a, args.b]);
  } catch (err) {
    console.error(`ValueError: ${err.message}`);
    process.exit(1);
  }
  const result = struct.parse(data);
  console.log(String(result));
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main();
}

