// Minimal mimic of the `construct` library's Struct/Int8ul/Container,
// operating on plain arrays of byte integers (no DataView/ArrayBuffer/Buffer).

// Field-type descriptor for an unsigned 8-bit integer (1 byte).
export const Int8ul = {
  name: 'Int8ul',
  size: 1,
  // data: plain array of integers; offset: index to read from.
  parse(data, offset) {
    return data[offset];
  },
};

export class Container {
  constructor(pairs = []) {
    this._pairs = [];
    for (const [name, value] of pairs) {
      this._pairs.push([name, value]);
      this[name] = value;
    }
  }

  toString() {
    const lines = this._pairs.map(([name, value]) => `    ${name} = ${value}`);
    return ['Container: ', ...lines].join('\n');
  }
}

export class Struct {
  // fields: array of [name, type] pairs, e.g. [['field1', Int8ul], ...]
  constructor(fields) {
    this.fields = fields;
  }

  // data: plain array of byte integers; returns a Container.
  parse(data) {
    let offset = 0;
    const pairs = [];
    for (const [name, type] of this.fields) {
      if (offset + type.size > data.length) {
        throw new Error(
          `could not read enough bytes for field '${name}', stream exhausted`,
        );
      }
      const value = type.parse(data, offset);
      offset += type.size;
      pairs.push([name, value]);
    }
    return new Container(pairs);
  }
}

// Mimics Python bytes([...]): validates every element is an integer in 0..255.
export function bytesFromInts(values) {
  for (const v of values) {
    if (!Number.isInteger(v) || v < 0 || v > 255) {
      throw new Error('bytes must be in range(0, 256)');
    }
  }
  return Array.from(values);
}

