// Throwaway test double matching the shared contract for parseArgs.
const USAGE_OPTS = '[-h] --a A --b B';

function usage(prog) {
  return `usage: ${prog} ${USAGE_OPTS}`;
}

function errorExit(prog, msg) {
  console.error(usage(prog));
  console.error(`${prog}: error: ${msg}`);
  process.exit(2);
}

function pyInt(s, argName, prog) {
  const t = s.trim();
  if (!/^[+-]?\d(?:_?\d)*$/.test(t)) {
    errorExit(prog, `argument ${argName}: invalid int value: '${s}'`);
  }
  return parseInt(t.replace(/_/g, ''), 10);
}

export function parseArgs(argv, prog) {
  const values = {};
  const extras = [];
  for (let i = 0; i < argv.length; i++) {
    let tok = argv[i];
    if (tok === '-h' || tok === '--help') {
      console.log(usage(prog));
      console.log('');
      console.log('options:');
      console.log('  -h, --help  show this help message and exit');
      console.log('  --a A');
      console.log('  --b B');
      process.exit(0);
    }
    let name = null, inline = null;
    if (tok === '--a' || tok === '--b') {
      name = tok;
    } else if (tok.startsWith('--a=')) {
      name = '--a'; inline = tok.slice(4);
    } else if (tok.startsWith('--b=')) {
      name = '--b'; inline = tok.slice(4);
    } else {
      extras.push(tok);
      continue;
    }
    let val;
    if (inline !== null) {
      val = inline;
    } else {
      i++;
      if (i >= argv.length) errorExit(prog, `argument ${name}: expected one argument`);
      val = argv[i];
    }
    values[name] = pyInt(val, name, prog);
  }
  const missing = [];
  if (!('--a' in values)) missing.push('--a');
  if (!('--b' in values)) missing.push('--b');
  if (missing.length) {
    errorExit(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length) {
    errorExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }
  return { a: values['--a'], b: values['--b'] };
}

