// Minimal re-implementation of the argparse behavior used by test4.mjs.
// Mirrors Python argparse: two required options --a and --b (type int),
// plus the automatic -h/--help option.

export function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

export function helpText(prog) {
  return [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
    '  --a A',
    '  --b B',
  ].join('\n');
}

function printHelpAndExit(prog) {
  process.stdout.write(helpText(prog) + '\n');
  process.exit(0);
}

function errorAndExit(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// Python int(str) with base 10: optional surrounding whitespace, optional
// sign, digits possibly separated by single underscores between digits.
const INT_PATTERN = /^[+-]?\d(?:_?\d)*$/;

function parsePythonInt(raw) {
  const s = raw.trim();
  if (!INT_PATTERN.test(s)) return null;
  const n = parseInt(s.replace(/_/g, ''), 10);
  return Number.isNaN(n) ? null : n;
}

// argparse's _negative_number_matcher: tokens like -1 or -1.5 are treated
// as values, not options (no option strings look like negative numbers).
const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  if (!token.startsWith('-')) return false;
  if (token === '-') return false;
  if (NEGATIVE_NUMBER_PATTERN.test(token)) return false;
  return true;
}

export function parseArgs(argv, prog) {
  const seen = {};
  const extras = [];
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelpAndExit(prog);
    }

    let name = null;
    let inlineValue = null;

    if (token === '--a' || token === '--b') {
      name = token;
    } else if (token.startsWith('--a=')) {
      name = '--a';
      inlineValue = token.slice(4);
    } else if (token.startsWith('--b=')) {
      name = '--b';
      inlineValue = token.slice(4);
    } else {
      extras.push(token);
      i += 1;
      continue;
    }

    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
      i += 1;
    } else {
      const next = i + 1 < argv.length ? argv[i + 1] : null;
      if (next === null || looksLikeOption(next)) {
        errorAndExit(prog, `argument ${name}: expected one argument`);
      }
      raw = next;
      i += 2;
    }

    const value = parsePythonInt(raw);
    if (value === null) {
      errorAndExit(prog, `argument ${name}: invalid int value: '${raw}'`);
    }
    seen[name] = value;
  }

  const missing = [];
  if (!('--a' in seen)) missing.push('--a');
  if (!('--b' in seen)) missing.push('--b');
  if (missing.length > 0) {
    errorAndExit(
      prog,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { a: seen['--a'], b: seen['--b'] };
}

