14	export class Container {
15	  constructor(pairs = []) {
16	    this._pairs = [];
17	    for (const [name, value] of pairs) {
18	      this._pairs.push([name, value]);
19	      this[name] = value;
20	    }
21	  }
22	
23	  toString() {
