29	export class Struct {
30	  // fields: array of [name, type] pairs, e.g. [['field1', Int8ul], ...]
31	  constructor(fields) {
32	    this.fields = fields;
33	  }
34	
35	  // data: plain array of byte integers; returns a Container.
36	  parse(data) {
37	    let offset = 0;
38	    const pairs = [];
39	    for (const [name, type] of this.fields) {
40	      if (offset + type.size > data.length) {
41	        throw new Error(
42	          `could not read enough bytes for field '${name}', stream exhausted`,
43	        );
44	      }
45	      const value = type.parse(data, offset);
46	      offset += type.size;
47	      pairs.push([name, value]);
48	    }
49	    return new Container(pairs);
50	  }
